/**
 * kon-blocks
 *
 * Lego-style block system for dynamic page layouts with drag & drop. Includes Hero, Text, Image, Video, Grid, Cards, Quote, CTA, Embed, Divider, and Spacer blocks.
 */
export interface BlocksApi {
  /**
   * List block types
   *
   * The block types a page can hold, each with the descriptor of its content fields.
   *
   * REST: `GET /api/page-builder/block-types` · scope `kon:blocks:block-types`
   * idempotent (safe to retry) · MCP tool `blocks__block-types`
   * Errors: `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly blockTypes: Operation<void, BlockTypesResponse>;
  /**
   * Clone a page
   *
   * Copies a page and its blocks as a new draft (never as homepage). Slug and title default to '<slug>-copy' and '<title> (Copy)'.
   *
   * REST: `POST /api/page-builder/pages/{id}/clone` · scope `kon:blocks:clone-page`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__clone-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly clonePage: Operation<ClonePageParams, ClonePageResponse>;
  /**
   * Add a block to a page
   *
   * Appends a block (after the last one unless sortOrder is given). The content is sanitized for its type before it is stored.
   *
   * REST: `POST /api/page-builder/pages/{pageId}/blocks` · scope `kon:blocks:create-block`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__create-block`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly createBlock: Operation<CreateBlockParams, CreateBlockResponse>;
  /**
   * Create a page
   *
   * Creates a page (draft by default) and, optionally, its blocks. The slug is derived from the title when missing. Making it the homepage needs a staff account.
   *
   * REST: `POST /api/page-builder/pages` · scope `kon:blocks:create-page`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__create-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly createPage: Operation<CreatePageParams, CreatePageResponse>;
  /**
   * Create a block template
   *
   * Saves a reusable block (name, block type and content).
   *
   * REST: `POST /api/page-builder/templates` · scope `kon:blocks:create-template`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__create-template`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly createTemplate: Operation<CreateTemplateParams, CreateTemplateResponse>;
  /**
   * Delete a block
   *
   * Removes one block from its page.
   *
   * REST: `DELETE /api/page-builder/blocks/{id}` · scope `kon:blocks:delete-block`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `blocks__delete-block`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly deleteBlock: Operation<DeleteBlockParams, DeleteBlockResponse>;
  /**
   * Delete a page
   *
   * Deletes a page and all its blocks. Cannot be undone.
   *
   * REST: `DELETE /api/page-builder/pages/{id}` · scope `kon:blocks:delete-page`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `blocks__delete-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly deletePage: Operation<DeletePageParams, DeletePageResponse>;
  /**
   * Duplicate a block
   *
   * Copies a block to the end of the same page (name gets a '(Copy)' suffix).
   *
   * REST: `POST /api/page-builder/blocks/{id}/duplicate` · scope `kon:blocks:duplicate-block`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__duplicate-block`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly duplicateBlock: Operation<DuplicateBlockParams, DuplicateBlockResponse>;
  /**
   * Get a page with its blocks
   *
   * One page by uuid or slug, with its visible blocks in order (block content sanitized). Drafts and session-only pages are a 404 for whoever cannot see them.
   *
   * REST: `GET /api/page-builder/pages/{id}` · scope `kon:blocks:get-page`
   * idempotent (safe to retry) · MCP tool `blocks__get-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly getPage: Operation<GetPageParams, GetPageResponse>;
  /**
   * List pages
   *
   * Paginated list of page-builder pages, newest update first. The public (and any caller without the content role) only sees published pages that do not require a session; staff and agents with content:edit can filter by any status.
   *
   * REST: `GET /api/page-builder/pages` · scope `kon:blocks:list-pages`
   * idempotent (safe to retry) · MCP tool `blocks__list-pages`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listPages: PageableOperation<ListPagesParams, ListPagesResponse, ListPagesItem>;
  /**
   * List block templates
   *
   * Active block templates, most used first, optionally filtered by category or block type.
   *
   * REST: `GET /api/page-builder/templates` · scope `kon:blocks:list-templates`
   * idempotent (safe to retry) · MCP tool `blocks__list-templates`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listTemplates: Operation<ListTemplatesParams, ListTemplatesResponse>;
  /**
   * Publish one block as its own page
   *
   * Creates (201) or updates (200, same slug) a page that holds exactly one block. Republishing replaces the previous block instead of duplicating it, so it is safe to call again with the same slug.
   *
   * REST: `POST /api/page-builder/pages/from-block` · scope `kon:blocks:publish-block-as-page`
   * idempotent (safe to retry) · MCP tool `blocks__publish-block-as-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly publishBlockAsPage: Operation<PublishBlockAsPageParams, PublishBlockAsPageResponse>;
  /**
   * Render a published page
   *
   * A published page ready to paint: page metadata plus visible blocks (scheduled visibility applied) with transform URLs for their media. Session-only pages need a session.
   *
   * REST: `GET /api/page-builder/render/{slug}` · scope `kon:blocks:render-page`
   * idempotent (safe to retry) · MCP tool `blocks__render-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly renderPage: Operation<RenderPageParams, RenderPageResponse>;
  /**
   * Reorder the blocks of a page
   *
   * Sets sortOrder for up to 500 blocks of the page in one go. Blocks of other pages are ignored. Sending the same order twice leaves the same state.
   *
   * REST: `POST /api/page-builder/pages/{pageId}/blocks/reorder` · scope `kon:blocks:reorder-blocks`
   * idempotent (safe to retry) · MCP tool `blocks__reorder-blocks`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly reorderBlocks: Operation<ReorderBlocksParams, ReorderBlocksResponse>;
  /**
   * Update a block
   *
   * Changes the given block fields; new content is sanitized for the block type.
   *
   * REST: `PATCH /api/page-builder/blocks/{id}` · scope `kon:blocks:update-block`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__update-block`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly updateBlock: Operation<UpdateBlockParams, UpdateBlockResponse>;
  /**
   * Update a page
   *
   * Changes the given page fields. Publishing sets publishedAt when it was empty; changing the slug checks it is free; isHomepage needs a staff account.
   *
   * REST: `PATCH /api/page-builder/pages/{id}` · scope `kon:blocks:update-page`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__update-page`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly updatePage: Operation<UpdatePageParams, UpdatePageResponse>;
  /**
   * Count one use of a template
   *
   * Increments the usage counter of a template (it orders the template list).
   *
   * REST: `POST /api/page-builder/templates/{id}/use` · scope `kon:blocks:use-template`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__use-template`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly useTemplate: Operation<UseTemplateParams, UseTemplateResponse>;
}
